// ---- JSON Schema to compact type ------------------------------------------------
const indent = (depth: number): string => '  '.repeat(depth);
const isObj = (v: unknown): v is JsonSchema => typeof v === 'object' && v !== null;
const lit = (v: unknown): string => JSON.stringify(v);

const stringConstraints = (s: JsonSchema): string[] => {
  const out: string[] = [];
  const format = typeof s['format'] === 'string' ? s['format'] : undefined;
  if (format) out.push(format);
  const min = s['minLength'];
  const max = s['maxLength'];
  if (typeof min === 'number' && typeof max === 'number' && min === max) out.push(`length ${min}`);
  else {
    if (typeof min === 'number') out.push(`min ${min}`);
    if (typeof max === 'number') out.push(`max ${max}`);
  }
  if (typeof s['pattern'] === 'string' && !format) out.push(`pattern /${s['pattern']}/`);
  return out;
};

const numberConstraints = (s: JsonSchema): string[] => {
  const out: string[] = [];
  const min = s['minimum'];
  const max = s['maximum'];
  if (typeof min === 'number' && min > -SAFE_INTEGER_MAX) out.push(`min ${min}`);
  if (typeof max === 'number' && max < SAFE_INTEGER_MAX) out.push(`max ${max}`);
  if (typeof s['exclusiveMinimum'] === 'number') out.push(`> ${s['exclusiveMinimum']}`);
  if (typeof s['exclusiveMaximum'] === 'number') out.push(`< ${s['exclusiveMaximum']}`);
  if (typeof s['multipleOf'] === 'number') out.push(`multiple of ${s['multipleOf']}`);
  return out;
};

const withConstraints = (base: string, constraints: string[]): string =>
  constraints.length > 0 ? `${base} (${constraints.join(', ')})` : base;

const commentFor = (s: JsonSchema): string => {
  const parts: string[] = [];
  if (typeof s['description'] === 'string')
    parts.push(s['description'].replace(/\s+/g, ' ').trim());
  if ('default' in s) parts.push(`default ${lit(s['default'])}`);
  return parts.length > 0 ? `  // ${parts.join('; ')}` : '';
};

/** Converts a JSON Schema node to a TS-like type. Continuation lines are indented for `depth`. */
const typeOf = (s: JsonSchema, depth: number): string => {
  if ('const' in s) return lit(s['const']);
  if (Array.isArray(s['enum'])) return s['enum'].map(lit).join(' | ');

  const variants = s['oneOf'] ?? s['anyOf'];
  if (Array.isArray(variants)) {
    const parts = [...new Set(variants.filter(isObj).map((v) => typeOf(v, depth + 1)))];
    if (parts.some((p) => p.includes('\n'))) {
      return parts.map((p) => `\n${indent(depth)}| ${p}`).join('');
    }
    return parts.join(' | ');
  }

  const type = s['type'];
  if (Array.isArray(type)) {
    const parts = [...new Set(type.map((t) => typeOf({ ...s, type: t }, depth)))];
    return parts.join(' | ');
  }

  switch (type) {
    case 'string':
      return withConstraints('string', stringConstraints(s));
    case 'integer':
    case 'number':
      return withConstraints(type, numberConstraints(s));
    case 'boolean':
      return 'boolean';
    case 'null':
      return 'null';
    case 'array': {
      const inner = isObj(s['items']) ? typeOf(s['items'], depth) : 'any';
      const constraints: string[] = [];
      if (typeof s['minItems'] === 'number') constraints.push(`min ${s['minItems']}`);
      if (typeof s['maxItems'] === 'number') constraints.push(`max ${s['maxItems']}`);
      if (s['uniqueItems'] === true) constraints.push('unique');
      const wrapped = /[\s|]/.test(inner) ? `Array<${inner}>` : `${inner}[]`;
      return withConstraints(wrapped, constraints);
    }
    case 'object':
      return objectType(s, depth);
    default:
      return s['properties'] ? objectType(s, depth) : 'any';
  }
};

const objectType = (s: JsonSchema, depth: number): string => {
  const props = isObj(s['properties']) ? s['properties'] : {};
  const required = new Set(Array.isArray(s['required']) ? (s['required'] as string[]) : []);
  const keys = Object.keys(props);
  const extra = s['additionalProperties'];
  if (keys.length === 0) {
    if (isObj(extra)) {
      const names = isObj(s['propertyNames']) ? s['propertyNames'] : undefined;
      const keyType =
        names && Array.isArray(names['enum']) ? names['enum'].map(lit).join(' | ') : 'string';
      return `Record<${keyType}, ${typeOf(extra, depth)}>`;
    }
    return '{}';
  }
  const lines = keys.map((key) => {
    const prop = props[key] as JsonSchema;
    const optional = required.has(key) ? '' : '?';
    const t = typeOf(prop, depth + 1);
    const sep = t.startsWith('\n') ? '' : ' ';
    return `${indent(depth + 1)}${key}${optional}:${sep}${t}${commentFor(prop)}`;
  });
  if (isObj(extra)) {
    lines.push(`${indent(depth + 1)}[key: string]: ${typeOf(extra, depth + 1)}`);
  }
  return `{\n${lines.join('\n')}\n${indent(depth)}}`;
};

/** Renders a Zod schema as a fenced TS-like block. `io` selects the input or output shape. */
export const renderSchema = (schema: z.ZodType, io: 'input' | 'output'): string => {
  const json = z.toJSONSchema(schema, {
    io,
    reused: 'inline',
    unrepresentable: 'any',
  }) as JsonSchema;
  delete json['$schema'];
  const body = typeOf(json, 0);
  return ['```ts', body.startsWith('\n') ? body.slice(1) : body, '```'].join('\n');
};

// ---- Markdown pieces -------------------------------------------------------------
const formatBytes = (n: number): string => {
  if (n >= 1024 * 1024) return `${n / (1024 * 1024)} MB`;
  if (n >= 1024) return `${n / 1024} KB`;
  return `${n} B`;
};

const escapeCell = (text: string): string => text.replace(/\|/g, '\\|');

const errorLine = (code: ErrorCode): string =>
  `- \`${ERROR_CODES[code]}\` \`${code}\`: ${ERROR_MEANINGS[code]}`;

const sortByCodeOrder = (codes: ErrorCode[]): ErrorCode[] =>
  [...new Set(codes)].sort((a, b) => ERROR_CODE_LIST.indexOf(a) - ERROR_CODE_LIST.indexOf(b));

const renderEndpoint = (e: EndpointDef): string => {
  const out: string[] = [];
  out.push(`### \`${e.method} ${e.path}\``, '', e.summary, '');

  const facts = [
    `**Auth:** \`${e.auth}\``,
    `**CSRF:** ${e.csrf ? 'required' : 'no'}`,
    ...(e.rateLimit ? [`**Rate limit:** \`${e.rateLimit}\``] : []),
    `**Success:** \`${e.response.status}\` ${e.response.kind}`,
    `**Id:** \`${e.id}\``,
  ];
  out.push(facts.join(' · '), '');

  if (e.params) out.push('**Path parameters**', '', renderSchema(e.params, 'input'), '');
  if (e.query) out.push('**Query**', '', renderSchema(e.query, 'input'), '');
  if (e.requestHeaders) {
    out.push('**Request headers**', '');
    for (const [name, desc] of Object.entries(e.requestHeaders)) out.push(`- \`${name}\`: ${desc}`);
    out.push('');
  }
  if (e.body) out.push('**Body** (`application/json`)', '', renderSchema(e.body, 'input'), '');
  if (e.rawBody) {
    const max = e.rawBody.maxBytes ? `, max ${formatBytes(e.rawBody.maxBytes)}` : '';
    out.push(
      `**Body** (raw, ${e.rawBody.contentTypes.map((t) => `\`${t}\``).join(' | ')}${max}): ${e.rawBody.description}`,
      '',
    );
  }

  out.push(`**Response \`${e.response.status}\`**`, '');
  if (e.response.schema) out.push(renderSchema(e.response.schema, 'output'), '');
  else if (e.response.kind === 'empty') out.push('No body.', '');
  else if (e.response.kind === 'tus') out.push('No JSON body (tus protocol).', '');
  else out.push(`Binary ${e.response.kind === 'stream' ? 'stream' : 'content'}.`, '');
  if (e.response.headers) {
    out.push('Response headers:', '');
    for (const [name, desc] of Object.entries(e.response.headers))
      out.push(`- \`${name}\`: ${desc}`);
    out.push('');
  }

  if (e.errors.length > 0) {
    out.push('**Errors**', '');
    for (const code of sortByCodeOrder([...e.errors])) out.push(errorLine(code));
    out.push('');
  }
  const implicit = sortByCodeOrder(implicitErrors(e).filter((c) => !e.errors.includes(c)));
  out.push(
    `Also possible: ${implicit.map((c) => `\`${ERROR_CODES[c]}\` \`${c}\``).join(', ')}.`,
    '',
  );

  if (e.notes) out.push(`**Notes:** ${e.notes}`, '');
  return out.join('\n');
};

const renderTusSection = (): string => {
  const out: string[] = ['### tus protocol', ''];
  for (const note of tusProtocolNotes) out.push(`- ${note}`);
  out.push(
    '',
    `**Upload-Metadata** (decoded; protocol \`Tus-Resumable: ${TUS_VERSION}\`, base path \`${TUS_BASE_PATH}\`)`,
    '',
    renderSchema(tusMetadataSchema, 'input'),
    '',
    '**Hook error mapping**',
    '',
    '| Hook | Error | HTTP | When |',
    '|---|---|---|---|',
  );
  for (const h of tusHookErrors) {
    out.push(`| \`${h.hook}\` | \`${h.code}\` | ${ERROR_CODES[h.code]} | ${escapeCell(h.when)} |`);
  }
  out.push('');
  return out.join('\n');
};

/** Renders the whole API contract as Markdown. Pure and deterministic. */
export const renderApiDocs = (endpoints: readonly EndpointDef[]): string => {
  const out: string[] = [API_DOCS_HEADER, '', '# easysend API contract', ''];
  out.push(
    `${endpoints.length} endpoints. Source of truth: the Zod schemas and the endpoint registry in \`packages/shared\`; this file is generated from them (\`pnpm api:docs\`, checked in CI).`,
    '',
    '## Decisions to approve',
    '',
  );
  CONTRACT_DECISIONS.forEach((d, i) => out.push(`${i + 1}. **${d.title}**: ${d.text}`));
  out.push('', '## Conventions', '', ...CONVENTIONS, '');

  out.push('### Auth levels', '', '| Level | Meaning |', '|---|---|');
  const levelText: Record<(typeof AUTH_LEVELS)[number], string> = {
    public: 'No authentication.',
    setup: 'Signed `es_setup` cookie, only while the setup is incomplete.',
    'mfa-pending': 'Password accepted, second factor still missing.',
    session: 'Any logged-in user.',
    admin: 'Logged-in user with the `admin` role.',
  };
  for (const level of AUTH_LEVELS) out.push(`| \`${level}\` | ${levelText[level]} |`);
  out.push('');

  out.push('## Error codes', '', '| Code | HTTP | Meaning |', '|---|---|---|');
  for (const code of ERROR_CODE_LIST) {
    out.push(`| \`${code}\` | ${ERROR_CODES[code]} | ${escapeCell(ERROR_MEANINGS[code])} |`);
  }
  out.push('');

  out.push('## Endpoint index', '', '| Method | Path | Auth | Summary |', '|---|---|---|---|');
  for (const e of endpoints) {
    out.push(`| ${e.method} | \`${e.path}\` | ${e.auth} | ${escapeCell(e.summary)} |`);
  }
  out.push('');

  for (const tag of ENDPOINT_TAGS) {
    const group = endpoints.filter((e) => e.tag === tag);
    if (group.length === 0) continue;
    const info = TAG_INFO[tag];
    out.push(`## ${info.title}`, '', info.intro, '');
    for (const e of group) out.push(renderEndpoint(e));
    if (tag === 'uploads') out.push(renderTusSection());
  }

  return `${out
    .join('\n')
    .replace(/\n{3,}/g, '\n\n')
    .trimEnd()}\n`;
};
